import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeeModal() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");

  const getVisibleFeeKeys = (cls) => {
    if (cls <= 5) return ["tuition", "development", "transport"];
    if (cls >= 6 && cls <= 9)
      return ["tuition", "development", "computer", "transport", "sports"];
    return ["tuition", "development", "computer", "transport", "sports", "artMusic"];
  };

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    try {
      const res = await axios.get(
        `http://localhost:5000/api/fees/student/${admissionNo}`
      );
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch {
      toast.error("Failed to load fee structure");
    }
  };

  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter valid amount");

    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      text: "Proceed to simulated payment?",
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const feeItems = summary.fee.items;
      const mainFeeKeys = getVisibleFeeKeys(Number(summary.student.className));

      const breakdown = {};
      let remainingAmount = amt;

      mainFeeKeys.forEach((k) => {
        if (!feeItems[k]) return;
        const rem = Math.max(
          0,
          feeItems[k].amount -
            (summary.payments?.reduce(
              (pSum, p) => pSum + (p.breakdown?.[k] || 0),
              0
            ) || 0)
        );
        if (remainingAmount >= rem) {
          breakdown[k] = rem;
          remainingAmount -= rem;
        } else {
          breakdown[k] = remainingAmount;
          remainingAmount = 0;
        }
      });

      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "simulated",
        breakdown,
      });

      if (res.data.success) {
        await Swal.fire({
          icon: "success",
          title: "Payment Successful!",
          html: `<p><b>Amount Paid:</b> ₹${amt}</p>`,
          confirmButtonText: "OK",
        });
        setSummary(null);
        setAdmissionNo("");
        setAmount("");
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch {
      toast.error("Payment failed");
    }
  };

  return (
    <div style={{ textAlign: "center" }}>
      <Toaster />
      <h3 style={{ marginBottom: "10px", color: "#003366" }}>
        Enter Admission Number
      </h3>
      <input
        type="text"
        value={admissionNo}
        onChange={(e) => setAdmissionNo(e.target.value)}
        placeholder="e.g. KV-000123"
        style={{
          width: "250px",
          height: "30px",
          borderRadius: "6px",
          border: "1px solid #ccc",
          padding: "5px 10px",
          marginBottom: "10px",
        }}
      />
      <button
        onClick={fetchFee}
        style={{
          marginLeft: "10px",
          background: "#0077b6",
          color: "#fff",
          padding: "6px 12px",
          borderRadius: "6px",
          border: "none",
          cursor: "pointer",
        }}
      >
        Search
      </button>

      {summary && (
        <div
          style={{
            marginTop: "20px",
            borderTop: "1px solid #ddd",
            paddingTop: "15px",
          }}
        >
          <h4>
            {summary.student.studentName} — Class {summary.student.className}
          </h4>
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              marginTop: "10px",
            }}
          >
            <thead>
              <tr style={{ background: "#f0f0f0" }}>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {getVisibleFeeKeys(Number(summary.student.className)).map((key) => (
                <tr key={key}>
                  <td>{summary.fee.items[key]?.title}</td>
                  <td>{summary.fee.items[key]?.amount}</td>
                </tr>
              ))}
            </tbody>
          </table>

          <div style={{ marginTop: "15px" }}>
            <input
              type="number"
              placeholder="Enter amount"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              style={{
                width: "180px",
                height: "30px",
                borderRadius: "6px",
                border: "1px solid #ccc",
                padding: "5px 10px",
              }}
            />
            <button
              onClick={payNow}
              style={{
                marginLeft: "10px",
                background: "#0077b6",
                color: "#fff",
                padding: "6px 12px",
                borderRadius: "6px",
                border: "none",
                cursor: "pointer",
              }}
            >
              Pay Now
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
